for (int i = 0; i < 3; i++) {
    final int snapshot = i; // kopia - effectively final
    Runnable r = () -> System.out.println(snapshot);
    r.run();
}
// petla for-each NIE MA tego problemu - zmienna petli tworzona od nowa w kazdej iteracji

int[] counter = {0}; // referencja effectively final, zawartosc mutowalna
Runnable inc = () -> counter[0]++;
inc.run();
inc.run();
System.out.println(counter[0]); // 2

class Greeter {
    String name;
    Runnable asLambda() {
        return () -> System.out.println(this.name); // this = Greeter
    }
    Runnable asAnonymousClass() {
        return new Runnable() {
            public void run() {
                System.out.println(Greeter.this.name); // this = anonimowa klasa!
            }
        };
    }
}

// BLAD: i nie jest effectively final (modyfikowana przez i++)
List<Runnable> tasks = new ArrayList<>();
for (int i = 0; i < 3; i++) {
    tasks.add(() -> System.out.println(i)); // BLAD KOMPILACJI
}

// POPRAWNIE: kopia licznika, effectively final
List<Runnable> tasks = new ArrayList<>();
for (int i = 0; i < 3; i++) {
    final int snapshot = i; // nowa zmienna, effectively final
    tasks.add(() -> System.out.println(snapshot));
}
